import re
from collections import Counter

FAIL = re.compile(r"Failed password for (?:invalid user )?(\S+) from (\S+)")
OK = re.compile(r"Accepted password for (\S+) from (\S+)")
fails, oks = Counter(), []
for line in log.splitlines():          # log: sshd 인증 로그 8줄(가상)
    if m := FAIL.search(line):
        fails[m.group(2)] += 1
    elif m := OK.search(line):
        oks.append((m.group(1), m.group(2)))

THRESHOLD = 5
for ip, n in fails.items():
    print(f"{ip}: 실패 {n}회", "→ 경보(무차별 대입 의심)" if n >= THRESHOLD else "")
for user, ip in oks:
    if fails[ip] >= THRESHOLD:
        print(f"!! {ip} 가 실패 {fails[ip]}회 뒤 {user} 로 로그인 성공 → 우선순위 높음")

